sys_script_client.script:
//MSSCUSTODY-7266

function onChange(control, oldValue, newValue, isLoading, isTemplate) {

    if (isLoading || newValue === '') {
        //console.log("fd1");
        hideInitialFields();
        g_form.setMandatory('sub_outcome', false);
        g_form.setDisplay('sub_outcome', false);

        g_form.setMandatory('transaction_reference', false);
        g_form.setDisplay('transaction_reference', false);

        g_form.setMandatory('amend_counterparty_code_ref', false);
        g_form.setDisplay('amend_counterparty_code_ref', false);

        g_form.setMandatory('switch_counterparty_code', false);
        g_form.setDisplay('switch_counterparty_code', false);

        //MSSCUSTODY-8300
        g_form.setDisplay('trade_link_reference', false);
        g_form.setDisplay('d_transaction_reference', false);
        g_form.setDisplay('d_transaction_type', false);
        g_form.setDisplay('d_settlement_quantity', false);
        g_form.setDisplay('d_legacy_status', false);
        g_form.setDisplay('d_hold_indicator', false);


        var tradeTaskType = g_scratchpad.blkTskRelated;
        var taskState = g_form.getValue('state').toString();

        if ((tradeTaskType == 'Maker') && ((taskState == '1') || (taskState == '2')) && oldValue == 'Switch Maintenance') {
            // console.log("fd2");
            // hideInitialFields();
            // g_form.setMandatory('sub_outcome', false);
            // g_form.setDisplay('sub_outcome', false);

            // g_form.setMandatory('transaction_reference', false);
            // g_form.setDisplay('transaction_reference', false);

            // g_form.setMandatory('amend_counterparty_code_ref', false);
            // g_form.setDisplay('amend_counterparty_code_ref', false);

            // g_form.setMandatory('switch_counterparty_code', false);
            // g_form.setDisabled('switch_counterparty_code', false);
            showTaskTradeDetails();
            showSubOutcomeSwitch();

        } else if ((tradeTaskType == 'Maker') && ((taskState == '1') || (taskState == '2')) && oldValue == 'Linking') {
            showTaskTradeDetails();
            showSubOutcomeLink();

        } else if ((tradeTaskType == 'Maker') && ((taskState == '1') || (taskState == '2'))) {
            hideInitialFields();
            g_form.setMandatory('sub_outcome', false);
            g_form.setDisplay('sub_outcome', false);

            g_form.setMandatory('transaction_reference', false);
            g_form.setDisplay('transaction_reference', false);

            g_form.setMandatory('amend_counterparty_code_ref', false);
            g_form.setDisplay('amend_counterparty_code_ref', false);

            g_form.setMandatory('switch_counterparty_code', false);
            g_form.setDisplay('switch_counterparty_code', false);

        } else if ((tradeTaskType == 'Checker') || (tradeTaskType == 'Maker') || (tradeTaskType.indexOf('GHSS') > -1)) {
            showFieldsForChecker();
        }
        return;

    }

    if (newValue === 'Switch Maintenance') {
        //g_form.addInfoMessage(oldValue);
        //console.log("fd3");
        showTaskTradeDetails();
        showSubOutcomeSwitch();

    } else if (newValue === 'Linking') {
        showTaskTradeDetails();
        showSubOutcomeLink();

    } else {
        g_form.setMandatory('sub_outcome', false);
        g_form.setDisplay('sub_outcome', false);
        g_form.setMandatory('transaction_reference_link', false);

        //MSSCUSTODY-8300
        g_form.setDisplay('trade_link_reference', false);
        g_form.setDisplay('d_transaction_reference', false);
        g_form.setDisplay('d_transaction_type', false);
        g_form.setDisplay('d_settlement_quantity', false);
        g_form.setDisplay('d_legacy_status', false);
        g_form.setDisplay('d_hold_indicator', false);

        hideInitialFields();
    }


    //---------------------------Functions---------------------------------

    function hideInitialFields() {
        var fieldsToHideInitial = getFieldsToHideInitial();
        fieldsToHideInitial.forEach(function(field) {
            g_form.setDisplay(field, false);
        });
    }

    function getFieldsToHideInitial() {
        return [
            'sub_outcome',
            'trade_legacy_status',
            'trade_location_code',
            'trade_scrip_hold_indicator',
            'trade_securities_account',
            'trade_settlement_amount',
            'trade_settlement_date',
            'trade_switch_account',
            'trade_quantity',
            'trade_transaction_type',
            'trade_transaction_reference',

            'transaction_reference',
            'transaction_type_display',
            'legacy_status_display',

            'amend_counterparty_code_ref',
            'switch_counterparty_code',

            'pair_switch_reference',

            'transaction_reference_link',
            'amend_cash_hold_indicator',
            'amend_gdi_indicator',
            'settle_link',
            'amend_script_hold_indicator'
        ];

    }


    function showTaskTradeDetails() {
        // setTimeout(function() {
        //     g_form.setMandatory('sub_outcome', true);
        //     g_form.setDisplay('sub_outcome', true);
        // }, 200);
        // g_form.clearOptions('sub_outcome');

        // g_form.addOption('sub_outcome', '', '--None--');
        // var ga1 = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
        // ga1.addParam('sysparm_name', 'getSwitchSuboutcome');
        // ga1.addParam('sysparm_sys_id', g_form.getUniqueValue());
        // ga1.getXMLAnswer(function(response) {
        //     var suboutcomesArr = JSON.parse(response);
        //     for (var i = 0; i < suboutcomesArr.length; i++) {
        //         g_form.addOption('sub_outcome', suboutcomesArr[i].value, suboutcomesArr[i].displayValue);
        //     }
        // });

        var ga2 = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
        ga2.addParam('sysparm_name', 'getTradeDetailsForSwitch');
        ga2.addParam('sysparm_sys_id', g_form.getUniqueValue());
        ga2.getXMLAnswer(function(response) {
            if (response) {
                var tradeData = JSON.parse(response);
                g_form.setDisplay('trade_legacy_status', true);
                g_form.setValue('trade_legacy_status', tradeData.tradeLegStatus ? tradeData.tradeLegStatus : '');
                g_form.setReadOnly('trade_legacy_status', true);

                g_form.setDisplay('trade_location_code', true);
                g_form.setValue('trade_location_code', tradeData.tradeLocCode);
                g_form.setReadOnly('trade_location_code', true);

                g_form.setDisplay('trade_scrip_hold_indicator', true);
                g_form.setValue('trade_scrip_hold_indicator', tradeData.tradeScripHold ? tradeData.tradeScripHold : '');
                g_form.setReadOnly('trade_scrip_hold_indicator', true);

                g_form.setDisplay('trade_securities_account', true);
                g_form.setValue('trade_securities_account', tradeData.tradeSecAccnt);
                g_form.setReadOnly('trade_securities_account', true);

                g_form.setDisplay('trade_settlement_amount', true);
                g_form.setValue('trade_settlement_amount', tradeData.tradeSettAmt);
                g_form.setReadOnly('trade_settlement_amount', true);

                g_form.setDisplay('trade_settlement_date', true);
                g_form.setValue('trade_settlement_date', tradeData.tradeSettDate);
                g_form.setReadOnly('trade_settlement_date', true);

                g_form.setDisplay('trade_switch_account', true);
                g_form.setValue('trade_switch_account', tradeData.tradeSwitchAccnt);
                g_form.setReadOnly('trade_switch_account', true);

                g_form.setDisplay('trade_quantity', true);
                g_form.setValue('trade_quantity', tradeData.tradeQuantity);
                g_form.setReadOnly('trade_quantity', true);

                g_form.setDisplay('trade_transaction_type', true);
                g_form.setValue('trade_transaction_type', tradeData.tradeTransType);
                g_form.setReadOnly('trade_transaction_type', true);

                g_form.setDisplay('trade_transaction_reference', true);
                g_form.setValue('trade_transaction_reference', tradeData.tradeTransRef);
                g_form.setReadOnly('trade_transaction_reference', true);

            }
        });
    }

    function showSubOutcomeSwitch() {
        setTimeout(function() {
            g_form.setMandatory('sub_outcome', true);
            g_form.setDisplay('sub_outcome', true);
        }, 200);
        g_form.clearOptions('sub_outcome');

        g_form.addOption('sub_outcome', '', '--None--');
        var ga1 = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
        ga1.addParam('sysparm_name', 'getSwitchSuboutcome');
        ga1.addParam('sysparm_sys_id', g_form.getUniqueValue());
        ga1.getXMLAnswer(function(response) {
            var suboutcomesArr = JSON.parse(response);
            for (var i = 0; i < suboutcomesArr.length; i++) {
                g_form.addOption('sub_outcome', suboutcomesArr[i].value, suboutcomesArr[i].displayValue);
            }
        });
    }

    function showSubOutcomeLink() {
        setTimeout(function() {
            g_form.setMandatory('sub_outcome', true);
            g_form.setDisplay('sub_outcome', true);
        }, 200);
        g_form.clearOptions('sub_outcome');

        g_form.addOption('sub_outcome', '', '--None--');
        var ga1 = new GlideAjax('x_hsb11_mss_c_proc.MSSCustodyBulkUtils');
        ga1.addParam('sysparm_name', 'getLinkSuboutcome');
        ga1.addParam('sysparm_sys_id', g_form.getUniqueValue());
        ga1.getXMLAnswer(function(response) {
            var suboutcomesArr = JSON.parse(response);
            for (var i = 0; i < suboutcomesArr.length; i++) {
                g_form.addOption('sub_outcome', suboutcomesArr[i].value, suboutcomesArr[i].displayValue);
            }
        });

        setTimeout(function() {
			g_form.setMandatory('value_date', false);
            g_form.setDisplay('value_date', false);
        }, 200);
    }

    function showFieldsForChecker() {
        //hideInitialFields();
        var outcome = g_form.getValue('outcome');
        if (outcome == 'Switch Maintenance' || outcome == 'Linking') {
            g_form.setDisplay('sub_outcome', true);
            g_form.setReadOnly('sub_outcome', true);

            g_form.setDisplay('trade_legacy_status', true);
            g_form.setReadOnly('trade_legacy_status', true);

            g_form.setDisplay('trade_location_code', true);
            g_form.setReadOnly('trade_location_code', true);

            g_form.setDisplay('trade_scrip_hold_indicator', true);
            g_form.setReadOnly('trade_scrip_hold_indicator', true);

            g_form.setDisplay('trade_securities_account', true);
            g_form.setReadOnly('trade_securities_account', true);

            g_form.setDisplay('trade_settlement_amount', true);
            g_form.setReadOnly('trade_settlement_amount', true);

            g_form.setDisplay('trade_settlement_date', true);
            g_form.setReadOnly('trade_settlement_date', true);

            g_form.setDisplay('trade_switch_account', true);
            g_form.setReadOnly('trade_switch_account', true);

            g_form.setDisplay('trade_quantity', true);
            g_form.setReadOnly('trade_quantity', true);

            g_form.setDisplay('trade_transaction_type', true);
            g_form.setReadOnly('trade_transaction_type', true);

            g_form.setDisplay('trade_transaction_reference', true);
            g_form.setReadOnly('trade_transaction_reference', true);
        }

    }
}
